contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint w) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(c).balance >= w);

        uint cBefore = address(c).balance;
        uint selfBefore = address(this).balance;

        c.withdraw(w); if (__ESBMC_reverted()) return;

        uint cAfter = address(c).balance;
        uint selfAfter = address(this).balance;

        assert(cBefore + selfBefore == cAfter + selfAfter);
    }

    receive() external payable {}
}

