// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 w) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(c).balance >= w);
        uint cBefore = address(c).balance;
        uint selfBefore = address(this).balance;
        try c.withdraw(w) {} catch { return; }
        uint cAfter = address(c).balance;
        uint selfAfter = address(this).balance;
        assertTrue(cBefore + selfBefore == cAfter + selfAfter);
    }

    function testFuzz_run(uint256 w) public {
        _run(w);
    }

    receive() external payable {}
}
